namespace RcsMap {
 public partial class Editor {
  void EditApplication(){
   canvas.CancelInteraction();StopPreview();var candidate=doc.Clone();
   if(candidate.Application==null)candidate.Application=new ApplicationSettings();candidate.Version=Math.Max(candidate.Version,7);
   using(var dialog=new ApplicationDialog(candidate))if(dialog.ShowDialog(this)==DialogResult.OK){BeginChange();doc=candidate;EndChange();}
  }
 }
 public sealed class ApplicationDialog:Form {
  readonly MapDocument document;readonly ListBox states=new ListBox();readonly ListBox transitions=new ListBox();
  readonly PropertyGrid settings=new PropertyGrid();readonly Label help=new Label();readonly TextBox includes=new TextBox();bool refreshing;
  public static T Copy<T>(T value){using(var stream=new MemoryStream()){var serializer=new DataContractJsonSerializer(typeof(T));serializer.WriteObject(stream,value);stream.Position=0;return (T)serializer.ReadObject(stream);}}
  public ApplicationDialog(MapDocument candidate){
   document=candidate;Text="应用与状态机 · 配置生成上电任务";Size=new Size(1160,790);MinimumSize=new Size(1040,700);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=3,Padding=new Padding(10)};root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,32));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,34));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,34));root.RowStyles.Add(new RowStyle(SizeType.Absolute,88));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));Controls.Add(root);
   help.Text="① 配置总闸与启动方式  ② 编辑状态与代码  ③ 按优先级添加转移\r\n每周期最多一次转移；第一条为真的条件胜出。内建路线状态自动执行全部航点流程，不需要机构上下文。\r\n起点确认是实物摆放约定，不是测量；用户代码必须非阻塞。旧地图默认不启用应用。";help.Dock=DockStyle.Fill;root.Controls.Add(help,0,0);root.SetColumnSpan(help,3);
   var config=new GroupBox{Text="应用配置",Dock=DockStyle.Fill};settings.SelectedObject=document.Application;settings.Dock=DockStyle.Fill;settings.ToolbarVisible=false;settings.PropertySort=PropertySort.NoSort;config.Controls.Add(settings);root.Controls.Add(config,0,1);
   var middle=new GroupBox{Text="状态列表",Dock=DockStyle.Fill};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3};layout.RowStyles.Add(new RowStyle(SizeType.Percent,70));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,110));layout.RowStyles.Add(new RowStyle(SizeType.Percent,30));middle.Controls.Add(layout);states.Dock=DockStyle.Fill;states.HorizontalScrollbar=true;layout.Controls.Add(states);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(buttons);Button(buttons,"添加状态",AddState);Button(buttons,"编辑代码",EditState);Button(buttons,"设为初态",Initial);Button(buttons,"上移",()=>MoveState(-1));Button(buttons,"下移",()=>MoveState(1));Button(buttons,"删除",RemoveState);includes.Multiline=true;includes.AcceptsReturn=true;includes.AcceptsTab=true;includes.ScrollBars=ScrollBars.Both;includes.WordWrap=false;includes.Dock=DockStyle.Fill;includes.Font=new Font("Consolas",10);includes.Text=document.Application.Includes;layout.Controls.Add(includes);root.Controls.Add(middle,1,1);
   var right=new GroupBox{Text="所选状态的转移 优先级从上到下",Dock=DockStyle.Fill};transitions.Dock=DockStyle.Fill;transitions.HorizontalScrollbar=true;right.Controls.Add(transitions);var edgeButtons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=110};right.Controls.Add(edgeButtons);Button(edgeButtons,"添加转移",()=>EditTransition(true));Button(edgeButtons,"编辑",()=>EditTransition(false));Button(edgeButtons,"上移",()=>MoveTransition(-1));Button(edgeButtons,"下移",()=>MoveTransition(1));Button(edgeButtons,"删除",RemoveTransition);root.Controls.Add(right,2,1);
   var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var ok=new Button{Text="确定",Width=105,Height=34};ok.Click+=(s,e)=>{try{settings.Focus();document.Application.Includes=includes.Text;ApplicationRules.Check(document);DialogResult=DialogResult.OK;}catch(Exception error){MessageBox.Show(this,error.Message,"状态机配置未完成");}};bottom.Controls.Add(ok);bottom.Controls.Add(new Button{Text="取消",DialogResult=DialogResult.Cancel,Width=105,Height=34});root.Controls.Add(bottom,0,2);root.SetColumnSpan(bottom,3);CancelButton=(Button)bottom.Controls[1];
   states.SelectedIndexChanged+=(s,e)=>RefreshTransitions();states.DoubleClick+=(s,e)=>EditState();transitions.DoubleClick+=(s,e)=>EditTransition(false);RefreshStates();
  }
  static void Button(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=30};b.Click+=(s,e)=>action();parent.Controls.Add(b);}
  MachineState Current {get{return states.SelectedIndex<0?null:document.Application.States[states.SelectedIndex];}}
  void RefreshStates(int selected=0){refreshing=true;states.Items.Clear();foreach(var item in document.Application.States)states.Items.Add(item);if(states.Items.Count>0)states.SelectedIndex=Math.Min(Math.Max(0,selected),states.Items.Count-1);refreshing=false;RefreshTransitions();}
  void RefreshTransitions(){if(refreshing)return;transitions.Items.Clear();var state=Current;if(state==null)return;foreach(var edge in state.Transitions){var target=document.Application.States.FirstOrDefault(s=>s.Id==edge.TargetId);transitions.Items.Add((edge.Enabled?"":"[禁用] ")+(target==null?"目标已删除":target.Name)+" ← "+edge.Condition);}}
  void AddState(){var state=new MachineState();using(var dialog=new MachineStateDialog(state,document))if(dialog.ShowDialog(this)==DialogResult.OK){document.Application.States.Add(state);RememberHardware(state);RefreshStates(document.Application.States.Count-1);}}
  void EditState(){var original=Current;if(original==null)return;var copy=Copy(original);using(var dialog=new MachineStateDialog(copy,document))if(dialog.ShowDialog(this)==DialogResult.OK){document.Application.States[states.SelectedIndex]=copy;RememberHardware(copy);RefreshStates(states.SelectedIndex);}}
  void RememberHardware(MachineState state){if(state.DeviceReferences!=null&&state.DeviceReferences.Count>0){includes.Text=HardwareOperations.Include(includes.Text);document.Version=8;}}
  void Initial(){if(Current==null)return;string id=Current.Id;foreach(var state in document.Application.States)state.Initial=state.Id==id;RefreshStates(states.SelectedIndex);}
  void MoveState(int offset){int i=states.SelectedIndex,j=i+offset;if(i<0||j<0||j>=document.Application.States.Count)return;var current=Current;document.Application.States.RemoveAt(i);document.Application.States.Insert(j,current);RefreshStates(j);}
  void RemoveState(){var state=Current;if(state==null)return;if(document.Application.States.Any(s=>s.Transitions.Any(t=>t.TargetId==state.Id))){MessageBox.Show(this,"仍有转移引用此状态，请先调整或删除转移。");return;}int i=states.SelectedIndex;document.Application.States.RemoveAt(i);RefreshStates(i);}
  void EditTransition(bool add){var state=Current;if(state==null)return;int index=transitions.SelectedIndex;if(!add&&index<0)return;var edge=add?new MachineTransition():Copy(state.Transitions[index]);using(var dialog=new MachineTransitionDialog(edge,document.Application.States))if(dialog.ShowDialog(this)==DialogResult.OK){if(add)state.Transitions.Add(edge);else state.Transitions[index]=edge;RefreshTransitions();}}
  void MoveTransition(int delta){var state=Current;int i=transitions.SelectedIndex,j=i+delta;if(state==null||i<0||j<0||j>=state.Transitions.Count)return;var edge=state.Transitions[i];state.Transitions.RemoveAt(i);state.Transitions.Insert(j,edge);RefreshTransitions();transitions.SelectedIndex=j;}
  void RemoveTransition(){if(Current==null||transitions.SelectedIndex<0)return;Current.Transitions.RemoveAt(transitions.SelectedIndex);RefreshTransitions();}
 }
 public sealed class MachineStateDialog:Form {
  public MachineStateDialog(MachineState state,MapDocument document=null){
   Text="状态代码 · "+state.Name;Size=new Size(900,710);MinimumSize=new Size(760,600);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);
   var properties=new PropertyGrid{Dock=DockStyle.Top,Height=190,SelectedObject=state,ToolbarVisible=false};Controls.Add(properties);var tabs=new TabControl{Dock=DockStyle.Fill};Controls.Add(tabs);tabs.BringToFront();string[] titles={"进入一次 enter","每周期 tick","完成表达式 complete","正常离开 exit","中止清理 cancel"};string[] values={state.Enter,state.Tick,state.Complete,state.Exit,state.Cancel};var code=new TextBox[5];for(int i=0;i<5;i++){var page=new TabPage(titles[i]);code[i]=new TextBox{Dock=DockStyle.Fill,Multiline=true,AcceptsTab=true,AcceptsReturn=true,WordWrap=false,ScrollBars=ScrollBars.Both,Text=values[i],Font=new Font("Consolas",10)};page.Controls.Add(code[i]);tabs.TabPages.Add(page);}
   var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=68};bar.Controls.Add(new Label{Text="全部区可用context；tick/complete另有elapsed_s，tick另有dt_s。内建类型自判完成，完成态结束。",AutoSize=true});if(document!=null){var hardware=new Button{Text="插入硬件操作…",AutoSize=true};hardware.Click+=(s,e)=>{try{using(var chooser=new HardwareOperationDialog(document))if(chooser.ShowDialog(this)==DialogResult.OK){state.Enter=code[0].Text;state.Complete=code[2].Text;state.Cancel=code[4].Text;var shadowDocument=new MapDocument{Devices=document.Devices,Version=8,Application=new ApplicationSettings{Includes=document.Application.Includes}};HardwareOperations.BindState(shadowDocument,state,chooser.Device,chooser.Operation,chooser.Value);code[0].Text=state.Enter;code[2].Text=state.Complete;code[4].Text=state.Cancel;properties.Refresh();}}catch(Exception error){MessageBox.Show(this,error.Message,"硬件操作未插入");}};bar.Controls.Add(hardware);var clear=new Button{Text="解除全部硬件引用",AutoSize=true};clear.Click+=(s,e)=>{state.DeviceReferences=null;state.HardwareOperations=null;};bar.Controls.Add(clear);}var ok=new Button{Text="确定",Width=95};ok.Click+=(s,e)=>{state.Enter=code[0].Text;state.Tick=code[1].Text;state.Complete=code[2].Text;state.Exit=code[3].Text;state.Cancel=code[4].Text;DialogResult=DialogResult.OK;};bar.Controls.Add(ok);bar.Controls.Add(new Button{Text="取消",DialogResult=DialogResult.Cancel});Controls.Add(bar);bar.BringToFront();
  }
 }
 public sealed class MachineTransitionDialog:Form {
  public MachineTransitionDialog(MachineTransition edge,System.Collections.Generic.List<MachineState> states){
   Text="状态转移 · 条件按列表优先级";Size=new Size(600,360);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(14)};Controls.Add(panel);panel.Controls.Add(new Label{Text="目标状态",AutoSize=true});var target=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=540};target.Items.AddRange(states.Cast<object>().ToArray());target.SelectedIndex=Math.Max(0,states.FindIndex(s=>s.Id==edge.TargetId));panel.Controls.Add(target);var enabled=new CheckBox{Text="启用",Checked=edge.Enabled,AutoSize=true};panel.Controls.Add(enabled);panel.Controls.Add(new Label{Text="C条件表达式：可用complete、elapsed_s、context；例如complete",AutoSize=true});var condition=new TextBox{Text=edge.Condition,Multiline=true,Width=540,Height=75};panel.Controls.Add(condition);var ok=new Button{Text="确定",Width=105};ok.Click+=(s,e)=>{if(target.SelectedItem==null||String.IsNullOrWhiteSpace(condition.Text)){MessageBox.Show(this,"请选择目标并填写条件表达式。");return;}edge.TargetId=((MachineState)target.SelectedItem).Id;edge.Condition=condition.Text;edge.Enabled=enabled.Checked;DialogResult=DialogResult.OK;};panel.Controls.Add(ok);panel.Controls.Add(new Button{Text="取消",DialogResult=DialogResult.Cancel,Width=105});
  }
 }
}
